fn solve(n: i8) -> i8 {
    // If the perimeter is odd, you can't form a rectangle with integer sides.
    if n % 2 != 0 {
        return 0;
    }

    // Now n is even.
    // - If n mod 4 == 2, answer is floor(n/4).
    // - If n mod 4 == 0, answer is n/4 - 1.
    match n % 4 {
        2 => n / 4,
        0 => n / 4 - 1,
        // This case cannot happen because we've already handled odd n above.
        _ => 0,
    }
}